function.arguments:
{"script":"() => {
  const text = document.body.innerText;
  const matches = [];
  let idx = 0;
  while ((idx = text.toLowerCase().indexOf('battery', idx)) >= 0) {
    matches.push({pos: idx, snippet: text.substring(idx, idx+200)});
    idx += 7;
  }
  return JSON.stringify(matches.slice(0, 10));
}"}

